    (r"$'\x67\x69\x74' $'\x61\x64\x64' -A", "broad"),
    (r"$'\147\151\164' $'\141\144\144' -A", "broad"),
    ("$'git' add -A", "broad"),
    ("git $'add' --all", "broad"),
    ("$''git a$''dd -A", "broad"),
    ("g$'i'\"t\" a$'d'd -A", "broad"),
    ("git ad$'d' -A", "broad"),
    ('git $"a"dd -A', "broad"),
